  "Carnivores + hoofed mammals, 77 million years ago": { es: "Carnívoros + ungulados, hace 77 millones de años", ar: "اللواحم + الحافريات، قبل 77 مليون سنة", zh: "食肉动物 + 有蹄类，7700万年前", sw: "Wanyama walao nyama + wanyama wenye kwato, miaka milioni 77 iliyopita", sv: "Rovdjur + hovdjur, för 77 miljoner år sedan" },
  "Carnivores, 55 million years ago": { es: "Carnívoros, hace 55 millones de años", ar: "اللواحم، قبل 55 مليون سنة", zh: "食肉动物，5500万年前", sw: "Wanyama walao nyama, miaka milioni 55 iliyopita", sv: "Rovdjur, för 55 miljoner år sedan" },
