  "African apes, 8.6 million years ago": { es: "Simios africanos, hace 8,6 millones de años", ar: "القردة العليا الأفريقية، قبل 8.6 مليون سنة", zh: "非洲猿类，860万年前", sw: "Nyani wakubwa wa Afrika, miaka milioni 8.6 iliyopita", sv: "Afrikanska människoapor, för 8,6 miljoner år sedan" },
  "Humans + chimpanzees, 6.4 million years ago": { es: "Humanos + chimpancés, hace 6,4 millones de años", ar: "البشر + الشمبانزي، قبل 6.4 مليون سنة", zh: "人类 + 黑猩猩，640万年前", sw: "Binadamu + sokwe, miaka milioni 6.4 iliyopita", sv: "Människor + schimpanser, för 6,4 miljoner år sedan" },
  "Chimpanzees + bonobos, 2 million years ago": { es: "Chimpancés + bonobos, hace 2 millones de años", ar: "الشمبانزي + البونوبو، قبل مليوني سنة", zh: "黑猩猩 + 倭黑猩猩，200万年前", sw: "Sokwe + bonobo, miaka milioni 2 iliyopita", sv: "Schimpanser + bonoboer, för 2 miljoner år sedan" },
